import re, ipaddress
def valid_ipv4(text):
    if not re.fullmatch(r"\d{1,3}(?:\.\d{1,3}){3}", text):
        return False
    try:
        ipaddress.IPv4Address(text)
    except ValueError:
        return False
    return True
