#!/usr/bin/env python3
"""top.py - count the first field of each input line, most frequent first."""
import sys
from collections import Counter

counts = Counter(line.split()[0] for line in sys.stdin if line.strip())
if not counts:
    print("top.py: no input", file=sys.stderr)
    sys.exit(1)
for item, n in counts.most_common():
    print(n, item)

