import re

LOG = re.compile(r'^(?P<ip>\S+) \S+ \S+ \[[^\]]+\] "(?P<method>[A-Z]+) (?P<path>\S+) [^"]*" (?P<status>\d{3}) (?P<bytes>\d+|-)')

def parse(line):
    m = LOG.match(line)
    if not m:
        return None
    return {
        "ip": m["ip"],
        "method": m["method"],
        "path": m["path"],
        "status": int(m["status"]),
        "bytes": 0 if m["bytes"] == "-" else int(m["bytes"]),
    }

import csv, io, json

def users_to_json(csv_text):
    rows = list(csv.DictReader(io.StringIO(csv_text)))
    for row in rows:
        row["port"] = int(row["port"])
    return json.dumps(rows, sort_keys=True)

