import re, ipaddress

def extract_ips(text):
    found = []
    for cand in re.findall(r"\b(?:\d{1,3}\.){3}\d{1,3}\b", text):
        try:
            ipaddress.IPv4Address(cand)
        except ValueError:
            continue
        if cand not in found:
            found.append(cand)
    return found

